
$bg-color: #0a0a0d;
$glass-bg: rgba(20, 20, 25, 0.6);
$border-gold: rgba(234, 179, 8, 0.4);
$accent-gold: #eab308;
$text-main: #e4e4e7;
$text-dim: #a1a1aa;
$glow-shadow: 0 0 15px rgba(234, 179, 8, 0.15);

.trpg-status-panel {
  position: relative;
  width: 100%;
  background: linear-gradient(180deg, #111116 0%, #08080a 100%);
  color: $text-main;
  font-family: 'Segoe UI', system-ui, sans-serif;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 4px;
  padding: 16px;
  box-shadow: inset 0 0 30px rgba(0,0,0,0.8), 0 4px 20px rgba(0,0,0,0.5);
  backdrop-filter: blur(12px);
}

.sys-menu-btn {
    position: absolute;
    top: 8px;
    right: 16px;
    z-index: 10;
    background: transparent;
    border: 1px solid rgba(255,255,255,0.1);
    color: $text-dim;
    width: 36px;
    height: 36px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;

    &:hover {
      background: rgba(255,255,255,0.05);
      color: #fff;
      border-color: $accent-gold;
      box-shadow: 0 0 8px rgba(234,179,8,0.2);
    }
  }

.panel-layout {
  display: flex;
  gap: 32px;
}

.left-column, .right-column {
  flex: 1;
  display: flex;
  flex-direction: column;
}

/* 分割线：黑魂风格细横线 */
.section-title {
  margin: 0 0 8px 0;
  font-size: 1rem;
  color: $text-main;
  font-weight: normal;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  letter-spacing: 1px;
}

/* 头部样式：头像与信息组合 */
.identity-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);

  .avatar-box {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    border: 2px solid $accent-gold;
    box-shadow: $glow-shadow;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0,0,0,0.5);
    flex-shrink: 0;

    .avatar-icon {
      width: 32px;
      height: 32px;
      color: $accent-gold;
    }
  }

  .identity-info {
    flex: 1;

    .char-name {
      margin: 0 0 4px 0;
      font-size: 1.5rem;
      font-weight: 600;
      color: #fff;
      letter-spacing: 2px;
      text-shadow: 0 0 10px rgba(255,255,255,0.2);
    }

    .status-line {
      font-size: 0.85rem;
      color: $text-dim;

      .status-alive {
        color: $accent-gold;
        font-family: monospace;
      }

      .separator {
        color: rgba(255,255,255,0.2);
        margin: 0 4px;
      }

      .gene-lock {
        color: #fff;
        text-shadow: 0 0 5px rgba(255,255,255,0.3);
      }
    }

    /* 血统/改造与评级 (可点击展开) */
    .bloodline-info {
      display: flex;
      justify-content: space-between;
      font-size: 0.95rem;
      color: $accent-gold;
      margin-top: 8px;
      padding: 6px 8px;
      border-radius: 4px;
      transition: all 0.2s;

      &.has-details {
        cursor: pointer;
        background: rgba(234, 179, 8, 0.05);
        border: 1px solid rgba(234, 179, 8, 0.2);

        &:hover {
          background: rgba(234, 179, 8, 0.1);
          box-shadow: $glow-shadow;
        }
      }

      .bloodline-name {
        font-weight: 500;
      }

      .bloodline-level {
        font-family: monospace;
      }
    }
  }


}

/* 全屏模态框与遮罩 */
.modal-overlay {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(4px);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

/* 侧边滑出抽屉菜单 */
.side-drawer {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 200px;
  background: #111116;
  border-left: 1px solid $border-gold;
  box-shadow: -5px 0 20px rgba(0,0,0,0.8);
  padding: 20px;
  display: flex;
  flex-direction: column;
  animation: slideInRight 0.3s ease forwards;

  .drawer-close-btn {
    position: absolute;
    top: 10px;
    right: 10px;
    background: none;
    border: none;
    color: $text-dim;
    font-size: 1.5rem;
    cursor: pointer;
    &:hover { color: #fff; }
  }

  .drawer-title {
    margin: 0 0 20px 0;
    color: $accent-gold;
    font-size: 1.1rem;
    border-bottom: 1px dotted rgba(234,179,8,0.3);
    padding-bottom: 8px;
  }

  .drawer-menu {
    display: flex;
    flex-direction: column;
    gap: 12px;

    .menu-btn {
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.1);
      color: #fff;
      padding: 10px;
      border-radius: 4px;
      cursor: pointer;
      text-align: left;
      transition: all 0.2s;

      &:hover {
        background: rgba(234,179,8,0.1);
        border-color: $accent-gold;
        box-shadow: $glow-shadow;
      }
    }
  }
}

@keyframes slideInRight {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

/* 居中内容模态框 */
.content-modal {
  position: relative;
  background: #111116;
  border: 1px solid $border-gold;
  border-radius: 8px;
  padding: 20px;
  width: 90%;
  max-width: 400px;
  max-height: 80%;
  box-shadow: 0 10px 30px rgba(0,0,0,0.9), $glow-shadow;
  display: flex;
  flex-direction: column;
  animation: popIn 0.3s ease forwards;

  &.large-modal {
    max-width: 500px;
  }

  .modal-close-btn {
    position: absolute;
    top: 12px;
    right: 12px;
    background: none;
    border: none;
    color: $text-dim;
    font-size: 1.5rem;
    cursor: pointer;
    &:hover { color: #ef4444; }
  }

  .modal-title {
    margin: 0 0 16px 0;
    color: #fff;
    font-size: 1.2rem;
    border-bottom: 1px solid rgba(234, 179, 8, 0.3);
    padding-bottom: 8px;

    .modal-level {
      color: $accent-gold;
      font-size: 0.85rem;
      font-weight: normal;
    }
  }

  .modal-body {
    flex: 1;
    overflow-y: auto;
    padding-right: 8px;

    &::-webkit-scrollbar { width: 6px; }
    &::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }
    &::-webkit-scrollbar-thumb { background: rgba(234,179,8,0.3); border-radius: 3px; }
    &::-webkit-scrollbar-thumb:hover { background: $accent-gold; }
  }
}

@keyframes popIn {
  from { transform: scale(0.95); opacity: 0; }
  to { transform: scale(1); opacity: 1; }
}

/* 模态框内部共用样式 (血统、物品、NPC) */
.pop-desc {
  font-size: 0.85rem;
  color: $text-dim;
  margin-bottom: 12px;
  line-height: 1.4;
}

.pop-section {
  margin-bottom: 12px;

  .pop-subtitle {
    font-size: 0.85rem;
    color: $accent-gold;
    margin-bottom: 6px;
  }

  .pop-attr-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;

    .pop-attr-tag {
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.1);
      padding: 2px 6px;
      border-radius: 4px;
      font-size: 0.75rem;
      color: #fff;
    }
  }

  .pop-trait-list {
    margin: 0;
    padding-left: 16px;
    font-size: 0.85rem;
    color: $text-main;

    li {
      margin-bottom: 6px;
      strong { color: #fff; }
    }
  }
}

/* 物品网格卡片 */
.item-grid {
  display: flex;
  flex-direction: column;
  gap: 10px;

  .empty-hint {
    text-align: center;
    color: $text-dim;
    padding: 20px;
    font-style: italic;
  }

  .item-card {
    background: rgba(255,255,255,0.02);
    border: 1px solid rgba(255,255,255,0.05);
    border-radius: 6px;
    padding: 10px;
    cursor: pointer;
    transition: all 0.2s;

    &:hover {
      background: rgba(255,255,255,0.05);
      border-color: rgba(234,179,8,0.3);
    }

    .item-header {
      display: flex;
      justify-content: space-between;
      margin-bottom: 4px;

      .item-name { color: #fff; font-weight: 500; font-size: 0.95rem; }
      .item-price { color: $accent-gold; font-family: monospace; font-size: 0.9rem; }
      .equip-badge { background: rgba(34,197,94,0.2); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 0.75rem; }
    }

    .item-meta {
      font-size: 0.8rem;
      color: $text-dim;
    }

    .item-detail-drawer {
      margin-top: 10px;
      padding-top: 10px;
      border-top: 1px dashed rgba(255,255,255,0.1);
      font-size: 0.85rem;
      color: $text-main;
      line-height: 1.4;
    }
  }
}

/* NPC 列表 */
.npc-list {
  display: flex;
  flex-direction: column;
  gap: 12px;

  .npc-card {
    background: rgba(255,255,255,0.02);
    border: 1px solid rgba(255,255,255,0.05);
    border-radius: 6px;
    padding: 12px;

    .npc-header {
      display: flex;
      justify-content: space-between;
      margin-bottom: 8px;

      .npc-name { color: #fff; font-weight: 500; }
      .npc-level { font-size: 0.8rem; }
      .npc-level.敌对 { color: #ef4444; }
      .npc-level.不友善 { color: #f97316; }
      .npc-level.友善 { color: #22c55e; }
      .npc-level.崇敬 { color: #a855f7; }
    }

    .npc-favor-bar {
      height: 4px;
      background: #1a1a24;
      border-radius: 2px;
      margin-bottom: 8px;
      overflow: hidden;
      .favor-fill { height: 100%; background: #ec4899; }
    }

    .npc-desc { font-size: 0.8rem; color: $text-dim; line-height: 1.3; }
  }
}

.fade-enter-active, .fade-leave-active {
  transition: opacity 0.3s, transform 0.3s;
}
.fade-enter-from, .fade-leave-to {
  opacity: 0;
  transform: translateY(-10px);
}

/* 列表行统一样式 (黑魂属性列表风格) */
.list-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  font-size: 0.95rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);

  .label { color: $text-dim; }
  .value { color: #fff; font-family: monospace; }

  /* 传奇属性专属特效 */
  .legendary-bonus {
    color: $accent-gold;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.8);
    font-weight: bold;
    margin-left: 2px;
  }
}

/* 资产区 */
.assets-section {
  margin-bottom: 24px;
}

.horizontal-assets {
  display: flex;
  justify-content: space-between;
  background: rgba(0, 0, 0, 0.3);
  padding: 8px 12px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.05);

  .h-asset {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;

    .label {
      font-size: 0.8rem;
      color: $text-dim;
    }
    .value {
      font-size: 1rem;
      color: $accent-gold;
      font-family: monospace;
      font-weight: bold;
    }
  }
}

/* 状态监控渐变条 */
.monitor-section {
  margin-bottom: 20px;

  .resource-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 8px;

    .res-label { width: 30px; font-size: 0.85rem; color: $text-dim; text-align: right; }
    .res-text { width: 80px; text-align: right; font-family: monospace; font-size: 0.85rem; color: #fff; }

    .res-bar-container {
      flex: 1;
      height: 6px;
      background: #1a1a24;
      border: 1px solid rgba(255,255,255,0.1);

      .res-bar {
        height: 100%;
        display: flex;

        .segment { height: 100%; transition: width 0.4s ease; }
      }

      &.hp-container .intact { background: #22c55e; }
      &.hp-container .shock { background: #eab308; }
      &.hp-container .lethal { background: #f97316; }
      &.hp-container .aggra { background: #ef4444; }

      &.wp-container .wp-fill { background: linear-gradient(90deg, #3b82f6, #60a5fa); box-shadow: 0 0 8px rgba(59,130,246,0.4); }
      &.ep-container .ep-fill { background: linear-gradient(90deg, #a855f7, #d946ef); box-shadow: 0 0 8px rgba(168,85,247,0.4); }
    }
  }
}

.derived-section {
  margin-bottom: 24px;
}

/* 技能滚动区 */
.skills-section {
  flex: 1;
  display: flex;
  flex-direction: column;

  .skills-scroll-area {
    flex: 1;
    max-height: 180px;
    overflow-y: auto;
    padding-right: 8px;

    &::-webkit-scrollbar { width: 4px; }
    &::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }
    &::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 2px; }
    &::-webkit-scrollbar-thumb:hover { background: $accent-gold; }

    .empty-hint {
      color: rgba(255,255,255,0.2);
      text-align: center;
      padding: 20px 0;
      font-style: italic;
      font-size: 0.85rem;
    }
  }
}

/* 响应式断点：当特别窄时转为单列 */
@media (max-width: 600px) {
  .panel-layout {
    flex-direction: column;
    gap: 20px;
  }
}
